import { PROPOSALS } from './catalog.js';
import { ConfirmationSound } from './media.js';
import { ANSWERS, CANDIDATES, AREAS, SESSION_KEY, createOrder, calculate, loadSession, saveSession } from './engine.js';

const app=document.querySelector('#app');
const paths={check:'m5 12 4 4L19 6',cross:'m6 6 12 12M18 6 6 18',arrow:'M4 12h15m-6-6 6 6-6 6',back:'M20 12H5m6-6-6 6 6 6',star:'m12 3 2.8 5.8 6.4.9-4.6 4.5 1.1 6.4-5.7-3-5.7 3 1.1-6.4-4.6-4.5 6.4-.9Z',question:'M9.2 8a3 3 0 0 1 5.6 1.5c0 2-2.8 2-2.8 4M12 17h.01',lock:'M7 11V7a5 5 0 0 1 10 0v4M6 11h12v10H6Zm6 4v2',leaf:'M20 4C9 3 3 8 6 16c6 5 15 0 14-12ZM4 21l11-11',economia:'M4 20h16M6 16V9m6 7V4m6 12v-5',seguranca:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z',saude:'M9 3h6v6h6v6h-6v6H9v-6H3V9h6Z',social:'m3 11 9-8 9 8M5 10v11h14V10M9 21v-7h6v7',costumes:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8M17 5a4 4 0 0 1 0 6m2 4a4 4 0 0 1 3 4v2',instituicoes:'m3 8 9-5 9 5H3ZM5 11v7m7-7v7m7-7v7M3 21h18',clock:'M12 7v5l3 2M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',mute:'m3 9 5 0 5-5v16l-5-5H3ZM17 9l5 6m0-6-5 6',volume:'m3 9 5 0 5-5v16l-5-5H3ZM16 8c3 2 3 6 0 8m3-11c5 4 5 10 0 14',share:'M12 16V3m-5 5 5-5 5 5M5 13v8h14v-8',external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12ZM12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',ballot:'M4 9v12h16V9M3 9h18M9 10l-3-5 10-4 3 6-10 4',play:'m8 4 12 8-12 8Z',pause:'M8 4v16M16 4v16',fullscreen:'M8 3H3v5m13-5h5v5M3 16v5h5m8 0h5v-5',reset:'M4 9a8 8 0 1 1 0 7M4 3v6h6'};
const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.check}"/></svg>`;
// Brand mark (concept "Urna", brand/logo): the ballot-box slot above the confirm check.
const brandMark='<svg viewBox="0 0 64 64" aria-hidden="true"><rect width="64" height="64" rx="15" fill="#194b39"/><rect x="17" y="11" width="30" height="5.5" rx="2.75" fill="#c8ee57"/><path d="M18.5 36 28.5 46 46.5 26.5" fill="none" stroke="#c8ee57" stroke-width="7" stroke-linecap="round" stroke-linejoin="round"/></svg>';
const themeIcons={'economia':'economia','seguranca':'seguranca','saude-educacao':'saude','programas-sociais':'social','meio-ambiente':'leaf','costumes':'costumes','instituicoes':'instituicoes'};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storage;try{storage=window.localStorage;}catch{storage=null;}
let session=loadSession(storage,PROPOSALS),view='home',busy=false,sound=true,revealTimer=null,filter='all',search='',review=false;
const confirmationSound=new ConfirmationSound();
let soundBlocked=false,motionObserver=null,landingCleanup=null,simTimers=[],confirmedInSim=false,noteEntry='rise';
const proposalMap=new Map(PROPOSALS.map(p=>[p.id,p]));
const chosen=()=>session.order.map(id=>proposalMap.get(id));
const result=()=>calculate(chosen(),session.answers);
function persist(){if(!saveSession(storage,session))toast('O armazenamento está bloqueado. Seu teste continua nesta aba.');}
function toast(text){const node=document.querySelector('#toast');node.textContent=text;node.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.hidden=true,5500);}
function header(){const inTest=['quiz','urn'].includes(view);return `<header class="site-header page"><a class="brand" href="#inicio" aria-label="voteAI, início"><span class="brand-symbol">${brandMark}</span>vote<span class="brand-ai">AI</span></a><nav aria-label="Navegação principal">${inTest?'<button class="text-button" data-action="home">Salvar e sair</button>':'<a href="#como-funciona">Como funciona</a><a href="#perguntas">Perguntas</a><a href="#fontes">Fontes e critérios</a>'}</nav><span class="election-label"><span></span> 2º turno <b>25/10</b></span></header>`;}
const footer=()=>`<footer class="site-footer page"><a class="brand brand-small" href="#inicio" aria-label="voteAI, início"><span class="brand-symbol">${brandMark}</span>vote<span class="brand-ai">AI</span></a><p>Uma decisão sua. Um teste independente.<br> Sem vínculo com partidos ou com a Justiça Eleitoral.</p><a href="#fontes">Metodologia e privacidade ${icon('arrow',16)}</a></footer>`;
function choiceButtons(demo=false){return `<div class="choices ${demo?'choices-demo':''}" role="group" aria-label="Responder à proposta"><button class="choice choice-disagree" aria-label="Discordo" data-answer="disagree" ${demo?'data-demo="true"':''}>${icon('cross')}<span>Discordo</span>${!demo?'<kbd aria-hidden="true">←</kbd>':''}</button><button class="choice choice-agree" aria-label="Concordo" data-answer="agree" ${demo?'data-demo="true"':''}>${icon('check')}<span>Concordo</span>${!demo?'<kbd aria-hidden="true">→</kbd>':''}</button><button class="choice choice-important" aria-label="Importante, concordo com peso dobrado" data-answer="important" ${demo?'data-demo="true"':''}>${icon('star')}<span>Importante</span><small>×2</small>${!demo?'<kbd aria-hidden="true">↑</kbd>':''}</button><button class="choice choice-skip" aria-label="Não sei" data-answer="skip" ${demo?'data-demo="true"':''}>${icon('question')}<span>Não sei</span>${!demo?'<kbd aria-hidden="true">↓</kbd>':''}</button></div>`;}
// Runoff for president: Sunday, 25 October 2026. Counted in whole calendar days on the visitor's clock.
const RUNOFF={y:2026,m:9,d:25,label:'25 de outubro de 2026'};
function runoffDays(now=new Date()){return Math.round((Date.UTC(RUNOFF.y,RUNOFF.m,RUNOFF.d)-Date.UTC(now.getFullYear(),now.getMonth(),now.getDate()))/864e5);}
function countdown(extra=''){const days=runoffDays();
  if(days<0)return `<p class="countdown countdown-past ${extra}">O 2º turno foi em ${RUNOFF.label}. As propostas continuam aqui para consulta.</p>`;
  if(days===0)return `<p class="countdown ${extra}"><span class="countdown-digits" aria-hidden="true"><b>H</b><b>J</b></span><span><strong>Hoje é dia de 2º turno.</strong> Conheça as ideias antes de votar.</span></p>`;
  const n=String(Math.min(days,99)).padStart(2,'0');
  return `<p class="countdown ${extra}"><span class="countdown-digits" aria-hidden="true" data-days="${n}"><b>${n[0]}</b><b>${n[1]}</b></span><span><strong>${days===1?'Falta 1 dia':`Faltam ${days} dias`}</strong> para o 2º turno, em ${RUNOFF.label}.</span></p>`;}
// Demo notes use proposals both candidates support, so the example never leans to one side.
const DEMO_NOTES=[{id:'sau-01',answer:'agree'},{id:'amb-01',answer:'important'},{id:'amb-05',answer:'disagree'},{id:'cos-06',answer:'agree'}];
let demoIndex=0;
// Real proposals for the moving strip: five from each candidate's plan and four shared, across the seven themes. No authorship shown.
const STRIP_NOTES=['eco-02','seg-05','sau-01','soc-04','amb-02','cos-04','ins-04','eco-04','seg-03','sau-05','soc-02','amb-01','cos-06','ins-03'];
const stripNote=id=>{const p=proposalMap.get(id);return `<li class="strip-note"><span class="topic">${icon(themeIcons[p.area],15)} ${AREAS[p.area]}</span><p>${esc(p.texto)}</p></li>`;};
const FAQ=[
  ['Isto é uma pesquisa eleitoral?','Não. O voteAI não registra voto, não soma respostas de ninguém e não prevê o resultado da eleição. Ele mostra um retrato das suas respostas a um recorte de propostas.'],
  ['De onde vêm as propostas?','Dos planos de governo de Lula e Flávio Bolsonaro registrados no TSE. Cada proposta aponta o documento e a página, e os textos foram reescritos em linguagem simples. Você confere tudo em Fontes e critérios.'],
  ['Por que o nome do candidato fica escondido?','Para você julgar a ideia, e não a pessoa. O nome de quem propôs cada item aparece só no final, junto com as fontes.'],
  ['Como a afinidade é calculada?','Concordo dá 1 ponto a quem apoia a proposta, Importante dá 2, Discordo dá 1 ponto ao outro lado e Não sei não conta. Os dois percentuais são independentes e não precisam somar 100%.'],
  ['Minhas respostas ficam guardadas?','Só neste aparelho, para você continuar de onde parou. Nada é enviado. Você pode apagar tudo em Fontes e critérios.'],
  ['Posso fazer o teste de novo?','Pode. Cada teste sorteia 25 das 50 propostas, sempre equilibradas entre os dois candidatos e os sete temas.'],
];
function home(){const demo=proposalMap.get(DEMO_NOTES[demoIndex].id);const saved=session&&session.index>0;
  const cta=saved?(session.index===25?'Ver meu resultado':'Continuar meu teste'):'Descobrir minha afinidade';
  const candidate=(id)=>{const c=CANDIDATES[id];return `<figure class="duel-card duel-${id}"><img src="${c.image}" alt="Retrato de ${c.name}" width="320" height="400" loading="lazy"><figcaption><strong>${c.name}</strong><span>${c.party} · ${c.number}</span></figcaption></figure>`;};
  return `<main id="main"><div class="hero-shell"><section class="hero page"><div class="hero-copy"><h1 class="hero-title"><span class="title-line">Vote nas ideias.</span><em><span class="title-line">Descubra</span><span class="title-line title-underlined">os nomes.<svg class="title-underline" viewBox="0 0 400 22" aria-hidden="true" preserveAspectRatio="none"><path d="M4 15 Q180 0 396 12" pathLength="1"/></svg></span></em></h1><p class="hero-description">Segundo turno para presidente: Lula ou Flávio Bolsonaro? Responda a 25 propostas sem saber de quem é cada uma e descubra com quem você mais concorda.</p><button class="button button-primary hero-cta" data-action="${saved?'resume':'start'}">${cta} ${icon('arrow')}</button><div class="hero-facts"><span>${icon('clock',16)} Cerca de 3 minutos</span><span>${icon('lock',16)} Sem cadastro</span></div>${saved?'<button class="text-button restart-link" data-action="start">Começar um novo teste</button>':''}${countdown('countdown-hero')}</div><div class="proposal-stage" aria-label="Demonstração: responda à proposta para começar o teste"><div class="note-stack demo-stack" style="--pad:6;--tilt:-.6deg"><span class="note-back note-back-3" aria-hidden="true"></span><span class="note-back note-back-2" aria-hidden="true"></span><span class="note-back note-back-1" aria-hidden="true"></span><article class="paper preview-paper note"><div class="paper-top"><span class="topic">${icon(themeIcons[demo.area],17)} ${AREAS[demo.area]}</span><span class="anonymous">${icon('lock',14)} Autoria oculta</span></div><p class="preview-proposal">${esc(demo.texto)}</p><p class="proposal-context">${esc(demo.contexto)}</p></article></div>${choiceButtons(true)}<p class="stage-caption">Pode experimentar: o nome só aparece no final.</p></div></section></div>
<section class="duel page" id="candidatos"><div class="duel-copy motion-reveal"><h2>Dois candidatos no 2º turno. Aqui, as ideias vêm primeiro.</h2><p>As propostas saem dos planos de governo que os dois registraram no TSE. No teste, você lê cada uma sem saber de quem é; os nomes só aparecem no resultado.</p></div><div class="duel-cards motion-reveal">${candidate('A')}<span class="duel-vs" aria-hidden="true">×</span>${candidate('B')}</div><p class="duel-note motion-reveal">Mesmo espaço, mesmo número de propostas exclusivas para cada um: 11 de cada lado e 3 que os dois apoiam.</p></section>
<section class="explainer-section page" id="video-explicativo"><div class="section-title-row motion-reveal"><h2>Como funciona, em 20 segundos.</h2><p>Sem som. Os textos aparecem na tela.</p></div><div class="explainer-frame motion-reveal"><video id="explainer-video" muted playsinline loop preload="metadata" poster="./assets/voteai-explainer-poster.png" aria-label="Vídeo explicativo: no 2º turno, leia 25 propostas sem os nomes, responda e veja na urna com quem você mais concorda"><source src="./assets/voteai-explainer.mp4" type="video/mp4"></video><button class="video-overlay" data-action="video-toggle" aria-label="Reproduzir vídeo explicativo">${icon('play',20)}</button></div></section>
<section class="how-section page" id="como-funciona"><h2 class="motion-reveal">Três passos, do jeito que você já conhece.</h2><ol class="how-steps"><li class="motion-reveal"><div class="step-art art-note" aria-hidden="true"><div class="mini-note mini-note-back"></div><div class="mini-note"><span class="topic">${icon('saude',13)} Saúde e educação</span><span class="anonymous">${icon('lock',11)} Autoria oculta</span><strong>Ter mais escolas públicas em tempo integral.</strong></div></div><h3>Leia a proposta, sem o nome.</h3><p>São 25 propostas reais, uma de cada vez, em linguagem simples e de sete temas diferentes.</p></li><li class="motion-reveal"><div class="step-art art-answers" aria-hidden="true"><span class="mini-choice mini-disagree">${icon('cross',14)} Discordo</span><span class="mini-choice mini-agree">${icon('check',14)} Concordo</span><span class="mini-choice mini-important">${icon('star',14)} Importante</span><span class="mini-choice mini-skip">? Não sei</span><span class="mini-stamp">Importante ×2</span></div><h3>Responda do seu jeito.</h3><p>Concorde, discorde ou pule. Se uma ideia pesa muito para você, marque Importante: ela vale o dobro.</p></li><li class="motion-reveal"><div class="step-art art-urn" aria-hidden="true"><div class="mini-lcd"><span>SEU VOTO PARA</span><strong>Presidente</strong><div class="mini-digits"><b></b><b></b></div></div></div><h3>A urna revela o resultado.</h3><p>Ela digita o número de quem mais combina com você e mostra o resultado por tema, com as fontes de cada proposta.</p></li></ol></section>
<section class="strip-section" aria-labelledby="strip-title"><div class="page strip-head motion-reveal"><h2 id="strip-title">Ideias de verdade, sobre a vida de todo mundo.</h2><ul class="topics-list">${Object.entries(AREAS).map(([id,label])=>`<li>${icon(themeIcons[id],16)}${label}</li>`).join('')}</ul></div><div class="strip-track-wrap"><ul class="strip-track">${STRIP_NOTES.map(stripNote).join('')}</ul><ul class="strip-track" aria-hidden="true">${STRIP_NOTES.map(stripNote).join('')}</ul></div></section>
<section class="trust page" id="por-que-confiar"><h2 class="motion-reveal">Feito para você decidir com calma.</h2><ul class="trust-list"><li class="motion-reveal"><strong>Fontes abertas.</strong> Cada proposta tem documento e página do plano de governo. Você confere tudo antes e depois.</li><li class="motion-reveal"><strong>Mesmo espaço para os dois.</strong> 11 propostas exclusivas de cada candidato e 3 que os dois apoiam, em todos os testes.</li><li class="motion-reveal"><strong>Nada sai do seu aparelho.</strong> Sem cadastro, sem coleta de respostas, sem anúncios. O cálculo acontece no seu navegador.</li><li class="motion-reveal"><strong>Não substitui o seu voto.</strong> O resultado é um retrato das suas respostas. A decisão continua sendo só sua.</li></ul></section>
<section class="faq page" id="perguntas"><h2 class="motion-reveal">Perguntas frequentes</h2><div class="faq-list motion-reveal">${FAQ.map(([q,a])=>`<details class="faq-item"><summary><span>${q}</span><span class="details-plus" aria-hidden="true">+</span></summary><p>${a}</p></details>`).join('')}</div></section>
<section class="final-cta page"><div class="closing-cta motion-reveal"><div><h2>Conheça as ideias antes de votar.</h2>${countdown('countdown-final')}</div><button class="button button-primary" data-action="${saved?'resume':'start'}">${saved?'Continuar meu teste':'Começar meu teste'} ${icon('arrow')}</button></div></section>
<div class="sticky-cta" hidden><button class="button button-primary" data-action="${saved?'resume':'start'}">${saved?'Continuar meu teste':'Começar meu teste'} ${icon('arrow')}</button></div></main>`;}
function steps(active){return `<div class="flow-steps" aria-label="Etapas do teste"><span class="${active===1?'active':'done'}">${active>1?icon('check',14):'<b>1</b>'} Suas opiniões</span><i></i><span class="${active===2?'active':active>2?'done':''}"><b>2</b> A urna</span><i></i><span class="${active===3?'active':''}"><b>3</b> Sua afinidade</span></div>`;}
// The proposal is the top sticky note of a pad: up to three notes peek out behind it and the pad edge thins as answers are given.
const noteTilts=[-.7,.5,-.3,.8,-.5,.35];
function noteStackOpen(){const left=25-session.index;const backs=[3,2,1].filter(n=>left>n).map(n=>`<span class="note-back note-back-${n}" aria-hidden="true"></span>`).join('');return `<div class="note-stack" style="--pad:${left-1};--tilt:${noteTilts[session.index%noteTilts.length]}deg">${backs}`;}
function quiz(){const p=proposalMap.get(session.order[session.index]);return `<main id="main" class="quiz-page page">${steps(1)}<div class="quiz-heading"><h1>Uma ideia. O que você pensa?</h1><p>O nome de quem propôs só aparece no final.</p></div><div class="quiz-wrap"><div class="progress-meta"><button class="text-button" data-action="back" ${session.index===0?'disabled':''}>${icon('back',16)} Voltar</button><button class="text-button quiz-sound" data-action="sound" aria-pressed="${sound}" aria-label="Som ${sound?'ativado':'desativado'}">${icon(sound?'volume':'mute',15)}</button><span>Proposta <strong>${session.index+1}</strong> de 25</span></div><div class="progress" role="progressbar" aria-label="Propostas respondidas" aria-valuemin="0" aria-valuemax="25" aria-valuenow="${session.index}"><span style="transform:scaleX(${session.index/25})"></span></div>${noteStackOpen()}<article class="paper quiz-paper note note-${noteEntry}" tabindex="-1" id="proposal-card"><div class="paper-top"><span class="topic">${icon(themeIcons[p.area],18)} ${AREAS[p.area]}</span><span class="anonymous">${icon('lock',14)} Autoria oculta</span></div><div class="proposal-copy" tabindex="0" role="region" aria-label="Texto e contexto da proposta"><h2>${esc(p.texto)}</h2><p class="proposal-context">${esc(p.contexto)}</p></div><div class="paper-bottom"><span>O que vale é a sua opinião.</span>${icon('ballot',20)}</div></article></div>${choiceButtons()}<p class="choice-help"><strong>Importante</strong> significa “concordo e isso pesa mais para mim”. Vale o dobro.</p><p class="keyboard-help">Use as setas do teclado ou arraste para os lados para concordar ou discordar.</p></div></main>`;}
function machine(r=null){const winner=r?.winner;return `<div class="machine ${r?'machine-revealed':''}" aria-label="Urna brasileira de simulação"><div class="machine-top"><span>voteAI</span><span>SIMULAÇÃO DE AFINIDADE</span><span class="machine-led"></span></div><div class="machine-body"><div class="screen-bezel"><div class="machine-screen" id="machine-screen" role="status" aria-live="polite">${r?screenResult(r):simScreen()}</div></div><div class="keypad"><div class="keypad-title">SEU VOTO É SEU</div><div class="number-keys">${[1,2,3,4,5,6,7,8,9].map(n=>`<button data-action="key" data-key="${n}" aria-label="Tecla ${n} da urna, ${r?'resultado revelado':'apurando suas respostas'}">${n}</button>`).join('')}<button class="zero-key" data-action="key" data-key="0" aria-label="Tecla zero da urna">0</button></div><div class="function-keys"><button class="key-white" data-action="blank">BRANCO</button><button class="key-orange" data-action="correct">CORRIGE</button><button class="key-green ${r?'':'confirm-ready'}" data-action="reveal">CONFIRMA</button></div></div></div><div class="machine-bottom"><span>PROPOSTAS PRIMEIRO. NOMES DEPOIS.</span><div class="speaker" aria-hidden="true"></div></div></div>`;}
// Laid out like the real urn: office on top, number on the left, name and party under it, portrait on the right.
function simScreen(){return `<span class="lcd-label">SEU VOTO PARA</span><div class="sim"><div class="sim-main"><strong class="sim-role">Presidente</strong><div class="sim-number-row"><span class="sim-field">Número:</span><div class="lcd-number sim-number" aria-hidden="true"><b data-slot="0"></b><b data-slot="1"></b></div></div><div class="sim-candidate" hidden></div></div><div class="sim-photo" aria-hidden="true"></div></div><div class="lcd-end"><span class="sim-hint">A urna vai digitar o número.</span></div>`;}
function screenResult(r){if(r.status!=='winner')return `<span class="lcd-label">APURAÇÃO CONCLUÍDA</span><div class="screen-neutral"><strong>${r.status==='tie'?'EMPATE':'SEM DADOS'}</strong><p>${r.status==='tie'?'A mesma afinidade com os dois candidatos.':'Responda a algumas propostas para calcular.'}</p></div><div class="lcd-end">FIM</div>`;const c=CANDIDATES[r.winner];return `<span class="lcd-label">MAIOR AFINIDADE COM SUAS RESPOSTAS</span><div class="lcd-candidate lcd-candidate-${r.winner}"><div><span>Presidência · 2026</span><div class="lcd-number"><b>${c.number[0]}</b><b>${c.number[1]}</b></div><strong>${c.name}</strong><span>${c.party}</span></div><img src="${c.image}" alt="Retrato de ${c.name}"></div><div class="lcd-end"><strong>${r.percentages[r.winner]}% de afinidade</strong><span>FIM</span></div>`;}
function urn(){return `<main id="main" class="urn-page page">${steps(2)}<div class="urn-heading"><h1>As ideias já têm seu voto.<br> <em>Agora, os nomes.</em></h1><p>Suas 25 respostas estão prontas. Deixe a urna fazer as contas.</p></div>${machine()}<div class="urn-actions"><span class="auto-reveal-label">Apuração automática</span><button class="text-button" data-action="sound" aria-pressed="${sound}">${icon('volume',17)} Som ${sound?'ativado':'desativado'}</button></div><p class="urn-disclaimer">Esta urna é uma simulação. Seu resultado não registra um voto.</p></main>`;}
function scoreRows(r){return ['B','A'].map(id=>{const c=CANDIDATES[id];return `<div class="score-row score-candidate-${id} ${r.winner===id?'score-winning':''}"><img src="${c.image}" alt="" width="48" height="48"><div class="score-info"><div><span>${c.name}<small>${c.party}</small></span><strong>${r.status==='empty'?'—':`${r.percentages[id]}<small>%</small>`}</strong></div><div class="score-track"><span class="candidate-${id}" style="width:${r.percentages[id]}%"></span></div></div></div>`;}).join('');}
function resultView(){const r=result();return `<main id="main" class="result-page page">${steps(3)}<div class="result-hero"><div class="result-device">${machine(r)}<p class="device-caption">As suas ideias, traduzidas em afinidade.</p></div><div class="result-summary"><span class="result-badge">${icon(r.status==='empty'?'question':'check',16)} ${r.status==='empty'?'Ainda não há respostas suficientes':'Apuração concluída'}</span><h1>${r.status==='winner'?`Nas ideias, você se aproxima mais de <em class="candidate-name-${r.winner}">${CANDIDATES[r.winner].name}.</em>`:r.status==='tie'?'Suas ideias encontraram <em>um empate.</em>':'Para descobrir, precisamos <em>da sua opinião.</em>'}</h1><p>${r.status==='empty'?'Você marcou Não sei em todas as propostas. Tudo bem: refaça o teste e responda às ideias sobre as quais tem uma opinião.':r.status==='tie'?'Suas respostas deram a mesma pontuação aos dois candidatos. Veja os temas e as fontes para entender o resultado.':'Este é um retrato das suas respostas a este conjunto de propostas. A escolha do voto continua com você.'}</p><div class="score-comparison">${scoreRows(r)}</div><div class="result-buttons"><button class="button button-primary" data-action="review">${icon('eye')} Ver minhas respostas</button><button class="button button-outline" data-action="share">${icon('share')} Compartilhar</button></div><button class="text-button" data-action="start">${icon('reset',16)} Fazer um novo teste</button><p class="result-footnote">${r.answered} opiniões · ${r.skipped} “Não sei” · Importante vale ×2<br> Os percentuais são independentes e podem não somar 100%.</p><button class="text-button repeat-sound" data-action="repeat-sound" ${soundBlocked?'':'hidden'}>${icon('volume',16)} Ouvir confirmação</button><div id="share-fallback" hidden></div></div></div><section class="theme-results"><div class="section-title-row"><h2>E em cada tema?</h2><span class="chart-legend"><b class="dot-B"></b>Lula <b class="dot-A"></b>Flávio Bolsonaro</span></div><div class="theme-table">${Object.entries(AREAS).map(([id,label])=>{const area=r.areas[id];const a=area?.weight?Math.round(area.scores.A/area.weight*100):null,b=area?.weight?Math.round(area.scores.B/area.weight*100):null;return `<div class="theme-row"><span>${icon(themeIcons[id],18)} ${label}</span><div class="theme-bars">${[['B',b],['A',a]].map(([c,p])=>`<div><div class="theme-track"><span class="candidate-${c}" style="width:${p??0}%"></span></div><small aria-label="${CANDIDATES[c].name}: ${p===null?'sem opinião':p+' por cento'}">${p===null?'—':p+'%'}</small></div>`).join('')}</div></div>`;}).join('')}</div></section><section class="review-section" id="review-section" ${review?'':'hidden'}><div class="section-title-row"><h2>Agora você sabe de quem é.</h2><span>Suas respostas e as fontes</span></div><p class="review-intro">Confira as posições dos candidatos e as referências dos documentos. “Sem posição” significa que não foi encontrada uma posição no recorte do plano.</p>${chosen().map(p=>proposalDetails(p,session.answers[p.id])).join('')}</section></main>`;}
function proposalDetails(p,answer=null){return `<details class="source-item"><summary><span class="source-topic">${icon(themeIcons[p.area],16)}${AREAS[p.area]}</span><strong>${esc(p.texto)}</strong>${answer?`<span class="answer-badge">${ANSWERS[answer].label}${answer==='important'?' ×2':''}</span>`:''}<span class="details-plus" aria-hidden="true">+</span></summary><div class="source-body"><p>${esc(p.contexto)}</p><div class="positions">${['B','A'].map(id=>`<span class="position-${id}"><strong>${CANDIDATES[id].name}</strong> ${p.posicoes[id]==='concorda'?'A favor':p.posicoes[id]==='discorda'?'Contra':'Sem posição'}</span>`).join('')}</div>${p.fontes.map(f=>`<a class="source-link" href="${esc(f.url)}#page=${f.pagina}" target="_blank" rel="noopener noreferrer">${CANDIDATES[f.candidato].name} · ${esc(f.documento)} · p. ${f.pagina} ${icon('external',15)}</a>`).join('')}</div></details>`;}
function sources(){return `<main id="main" class="sources-page page"><a class="text-button" href="#inicio">${icon('back',17)} Voltar ao início</a><div class="sources-heading"><h1>Você pode conferir<br> <em>cada ideia.</em></h1><p>Um resultado só faz sentido quando você sabe de onde ele veio.<br> Aqui estão o método, as propostas e as fontes.</p></div><section class="method-section"><h2>Como calculamos a afinidade</h2><div class="method-columns"><div><h3>Uma comparação às cegas</h3><p>O catálogo reúne 50 propostas de Lula e Flávio Bolsonaro, com referências aos planos de governo. Sorteamos 25: 11 exclusivas de cada candidato e 3 compartilhadas, distribuídas pelos sete temas.</p><p>O nome e a fonte ficam ocultos durante o teste. Cada ideia tem referências de documento e página. Este recorte não representa uma auditoria independente completa dos planos.</p></div><div><h3>As quatro respostas</h3><ul class="method-answers"><li><strong>Concordo</strong><span>1 ponto para quem apoia.</span></li><li><strong>Discordo</strong><span>1 ponto para o lado oposto.</span></li><li><strong>Importante</strong><span>Concordância com peso 2.</span></li><li><strong>Não sei</strong><span>Avança sem somar pontos.</span></li></ul></div><div><h3>O resultado, sem atalhos</h3><p>Cada percentual é a pontuação do candidato dividida pelo total de pesos das respostas válidas. Ambos podem pontuar na mesma proposta. Por isso os percentuais não precisam somar 100%.</p><p>Discordar de uma proposta exclusiva pontua para o outro candidato por uma regra de comparação. Isso não transforma “sem posição” em oposição documentada. Empates são exibidos sem desempate artificial.</p></div></div></section><section class="catalog-section"><div class="section-title-row"><h2>50 propostas. Fontes abertas.</h2><span>Planos de governo com documento e página</span></div><div class="catalog-controls"><label class="search-box">${icon('eye',18)}<input type="search" id="source-search" placeholder="Buscar nas propostas…" value="${esc(search)}" aria-label="Buscar nas propostas"></label><label class="area-filter"><span>Tema</span><select id="source-filter"><option value="all">Todos os temas</option>${Object.entries(AREAS).map(([id,label])=>`<option value="${id}" ${filter===id?'selected':''}>${label}</option>`).join('')}</select></label></div><p id="source-count" class="source-count"></p><div id="source-list"></div></section><section class="credits-section"><h2>Privacidade e créditos</h2><p>Não pedimos cadastro e não enviamos suas respostas. A sessão é guardada no armazenamento local deste navegador. Você pode apagá-la a qualquer momento. Compartilhar envia somente um resumo, mediante sua ação.</p><button class="button button-outline" data-action="clear">Apagar minhas respostas deste aparelho</button><p>Textos adaptados para o voteAI. Catálogo e referências recuperados em 14/10/2026; consulte os documentos originais em cada proposta. Teste independente de afinidade, sem vínculo com candidatos ou Justiça Eleitoral.</p><p>Retrato de Lula: Palácio do Planalto, <a href="https://commons.wikimedia.org/wiki/File:Foto_oficial_de_Luiz_In%C3%A1cio_Lula_da_Silva_(ombros).jpg" target="_blank" rel="noopener noreferrer">CC BY 2.0</a>. Retrato de Flávio Bolsonaro: <a href="https://commons.wikimedia.org/wiki/File:Foto_oficial_do_senador_Fl%C3%A1vio_Bolsonaro_(v._AgSen).jpg" target="_blank" rel="noopener noreferrer">Agência Senado, Atribuição</a>. Mesmos recorte e tratamento. Fontes Rubik, Fredoka, IBM Plex Mono, DotGothic16 e DM Sans (logo): Google Fonts, SIL OFL. Som de confirmação: <a href="https://www.myinstants.com/pt/instant/urna-eletronica-confirma/" target="_blank" rel="noopener noreferrer">gravação da urna eletrônica</a>, indicada para este projeto.</p></section></main>`;}
function render({focus=false,scroll=true}={}){
  document.querySelector('#explainer-video')?.pause();
  document.body.dataset.view=view;
  motionObserver?.disconnect();
  landingCleanup?.();landingCleanup=null;
  app.innerHTML=header()+({home,quiz,urn,result:resultView,sources}[view]())+footer();
  noteEntry='rise';
  document.title='voteAI — '+({home:'2º turno 2026: compare as ideias de Lula e Flávio Bolsonaro',quiz:'Sua opinião conta',urn:'Revele sua afinidade',result:'Seu resultado',sources:'Fontes e critérios'}[view]);
  if(view==='sources')filterSources();
  fitObserver?.disconnect();
  if(view==='quiz'){bindSwipe();bindFit();}
  if(view==='home')bindLandingMotion();
  if(view==='urn')queueMicrotask(reveal);
  if(scroll)window.scrollTo({top:0,behavior:'instant'});
  if(focus){const el=document.querySelector(view==='quiz'?'#proposal-card':'main h1');el?.setAttribute('tabindex','-1');el?.focus({preventScroll:true});}
}
function clearSim(){clearTimeout(revealTimer);simTimers.forEach(clearTimeout);simTimers=[];}
function navigate(next,{focus=true}={}){clearSim();busy=false;view=next;const hash={home:'#inicio',quiz:'#teste',urn:'#urna',result:'#resultado',sources:'#fontes'}[next];history.replaceState(null,'',hash);render({focus});}
function start(firstId=null){confirmationSound.stop();confirmationSound.unlock();session={version:1,order:createOrder(PROPOSALS,Math.random,firstId),answers:{},index:0,revealed:false};review=false;persist();navigate('quiz');}
function resume(){if(!session)return start();navigate(session.index===25?(session.revealed?'result':'urn'):'quiz');}
function answer(value){if(view!=='quiz'||busy)return;confirmationSound.unlock();busy=true;session.answers[session.order[session.index]]=value;
  const card=document.querySelector('#proposal-card');
  document.querySelectorAll('[data-answer]').forEach(b=>{b.disabled=true;b.classList.remove('is-leaning');});
  const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
  // Stamp the answer on the note, peel it from its free bottom edge (it is glued at the top), then send it the way of the answer.
  if(card){const s=noteStamp(card,value);s.classList.remove('is-preview');s.style.opacity='';}
  if(!reduced&&card?.animate){
    const [x,y]={agree:[1,0],disagree:[-1,0],important:[0,-1],skip:[0,1]}[value];
    const from=getComputedStyle(card).transform;
    // Taller notes peel at a smaller angle so the lifted edge never sweeps over the answer buttons.
    const peel=Math.max(6,Math.min(16,4400/card.offsetHeight));
    const lift=`perspective(900px) translateY(-8px) rotateX(${peel.toFixed(1)}deg) rotate(${(x||-y)*3}deg)`;
    const to=x?`translate(${x*125}%,-8%) rotate(${x*18}deg)`:y<0?'translate(0,-60%) rotate(-5deg) scale(1.03)':'translate(0,26%) rotate(4deg) scale(.92)';
    card.classList.add('is-leaving');
    card.animate([{transform:from==='none'?'none':from,opacity:1},{transform:lift,opacity:1,offset:.42,easing:'cubic-bezier(.45,0,1,.6)'},{transform:to,opacity:0}],{duration:520,easing:'cubic-bezier(.2,0,.3,1)',fill:'forwards'});
  }
  // Reduced motion keeps the stamp as feedback, without the travel.
  setTimeout(()=>{session.index++;session.revealed=false;persist();busy=false;if(session.index===25)navigate('urn');else render({focus:true,scroll:false});},reduced?380:500);
}
async function playConfirmation(){const played=await confirmationSound.play();soundBlocked=!played;if(!played){const button=document.querySelector('[data-action="repeat-sound"]');if(button)button.hidden=false;toast('O navegador bloqueou o som. Toque em Ouvir confirmação para reproduzir.');}}
function reveal(){if(view==='result'){toast('Seu resultado já foi revelado. Você pode revisar as respostas.');return;}if(view!=='urn'||busy)return;busy=true;confirmedInSim=false;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const r=result();
  document.querySelector('.machine').classList.add('machine-counting');
  document.querySelector('.urn-actions').innerHTML=`<button class="text-button" data-action="skip-animation">Pular animação ${icon('arrow',17)}</button><button class="text-button" data-action="sound" aria-pressed="${sound}">${icon(sound?'volume':'mute',17)} Som ${sound?'ativado':'desativado'}</button>`;
  if(r.status!=='winner'||reduced){
    if(r.status!=='winner')document.querySelector('#machine-screen').innerHTML=`<span class="lcd-label">APURANDO SUAS RESPOSTAS</span><div class="screen-counting"><strong>Um instante.</strong><p>Comparando propostas e prioridades…</p><div class="lcd-loader"><span></span></div></div><span class="lcd-label">25 PROPOSTAS · CÁLCULO LOCAL</span>`;
    revealTimer=setTimeout(finishReveal,reduced?0:2400);return;
  }
  // Simulation: the urn types the winner's two digits one at a time, shows the candidate, then confirms.
  const c=CANDIDATES[r.winner],digits=[...c.number],screen=document.querySelector('#machine-screen');
  const slots=screen.querySelectorAll('[data-slot]'),hint=screen.querySelector('.sim-hint'),card=screen.querySelector('.sim-candidate');
  const key=sel=>document.querySelector(sel);
  const press=el=>{if(!el)return;el.classList.add('is-pressed');confirmationSound.beep();setTimeout(()=>el.classList.remove('is-pressed'),170);};
  const at=(ms,fn)=>simTimers.push(setTimeout(fn,ms));
  const type=i=>{press(key(`[data-key="${digits[i]}"]`));slots[i].textContent=digits[i];slots[i].classList.remove('is-next');slots[i].classList.add('is-filled');slots[i+1]?.classList.add('is-next');hint.textContent=i?'Número completo.':'Digitando o número…';};
  slots[0].classList.add('is-next');
  at(900,()=>type(0));
  at(1800,()=>type(1));
  at(2500,()=>{card.hidden=false;card.innerHTML=`<span><span class="sim-field">Nome:</span> <strong>${c.name}</strong></span><span><span class="sim-field">Partido:</span> ${c.party}</span>`;screen.querySelector('.sim-photo').innerHTML=`<img src="${c.image}" alt="Retrato de ${c.name}">`;hint.textContent='Confira e confirme.';});
  at(3700,()=>{const ok=key('.key-green');press(ok);ok?.classList.remove('confirm-ready');confirmedInSim=true;playConfirmation();screen.innerHTML=`<span class="lcd-label">VOTO SIMULADO CONFIRMADO</span><div class="sim-fim"><strong>FIM</strong></div><div class="lcd-end"><span class="sim-hint">Calculando sua afinidade…</span></div>`;});
  at(5300,()=>finishReveal({sound:false}));
}
function finishReveal({sound:withSound=true}={}){clearSim();if(!session||view!=='urn')return;session.revealed=true;persist();const already=confirmedInSim;confirmedInSim=false;navigate('result');if(withSound&&!already)playConfirmation();}
function filterSources(){const q=search.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase();const list=PROPOSALS.filter(p=>(filter==='all'||p.area===filter)&&(p.texto+' '+p.contexto).normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase().includes(q));document.querySelector('#source-list').innerHTML=list.map(p=>proposalDetails(p)).join('')||'<div class="empty-search"><h3>Nenhuma proposta encontrada.</h3><p>Tente outra palavra ou escolha todos os temas.</p></div>';document.querySelector('#source-count').textContent=`${list.length} ${list.length===1?'proposta encontrada':'propostas encontradas'}`;}
function bindLandingMotion(){
  motionObserver?.disconnect();const reduced=matchMedia('(prefers-reduced-motion: reduce)');
  if(!reduced.matches){motionObserver=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){entry.target.classList.add('is-visible');motionObserver.unobserve(entry.target);}},{threshold:.15});document.querySelectorAll('.motion-reveal').forEach(el=>{el.classList.add('will-reveal');motionObserver.observe(el);});}
  const sticky=document.querySelector('.sticky-cta'),heroCta=document.querySelector('.hero-cta'),closing=document.querySelector('.closing-cta');
  if(sticky&&heroCta&&closing){let heroOut=false,closingIn=false;const show=()=>{sticky.hidden=!(heroOut&&!closingIn);};
    const ctaObserver=new IntersectionObserver(entries=>{for(const e of entries){if(e.target===heroCta)heroOut=!e.isIntersecting&&e.boundingClientRect.top<0;else closingIn=e.isIntersecting;}show();});
    ctaObserver.observe(heroCta);ctaObserver.observe(closing);const prevCleanup=landingCleanup;landingCleanup=()=>{ctaObserver.disconnect();prevCleanup?.();};}
  // Countdown digits roll up from 00 the first time they come into view, like the urn display.
  if(!reduced.matches){const roll=new IntersectionObserver(entries=>{for(const e of entries){if(!e.isIntersecting)continue;roll.unobserve(e.target);const target=+e.target.dataset.days,b=e.target.querySelectorAll('b'),t0=performance.now();
      const tick=t=>{const k=Math.min(1,(t-t0)/900),n=String(Math.round(target*(1-Math.pow(1-k,3)))).padStart(2,'0');b[0].textContent=n[0];b[1].textContent=n[1];if(k<1)requestAnimationFrame(tick);};requestAnimationFrame(tick);}},{threshold:.6});
    document.querySelectorAll('.countdown-digits[data-days]').forEach(el=>roll.observe(el));const prevRoll=landingCleanup;landingCleanup=()=>{roll.disconnect();prevRoll?.();};}
  // The demo note answers itself every few seconds: stamp, peel, next note. Any hover, focus or touch on it pauses the loop.
  const stage=document.querySelector('.proposal-stage'),demoCard=stage?.querySelector('.preview-paper');
  if(demoCard&&!reduced.matches&&demoCard.animate){let paused=false,visible=true;
    const pause=()=>{paused=true;},resume=()=>{paused=false;};
    stage.addEventListener('pointerenter',pause);stage.addEventListener('pointerleave',resume);stage.addEventListener('focusin',pause);stage.addEventListener('focusout',resume);stage.addEventListener('touchstart',pause,{passive:true});
    const seen=new IntersectionObserver(([e])=>{visible=e.isIntersecting;});seen.observe(stage);
    const step=()=>{if(paused||!visible||document.hidden||busy||!demoCard.isConnected)return;const cur=DEMO_NOTES[demoIndex];noteStamp(demoCard,cur.answer);
      const [x]={agree:[1],disagree:[-1],important:[0],skip:[0]}[cur.answer];
      const to=x?`translate(${x*80}%,-6%) rotate(${x*14}deg)`:'translate(0,-40%) rotate(-5deg)';
      const leave=demoCard.animate([{transform:'rotate(-.6deg)',opacity:1},{transform:'perspective(900px) translateY(-6px) rotateX(10deg) rotate(-.6deg)',opacity:1,offset:.5},{transform:to,opacity:0}],{duration:1000,easing:'cubic-bezier(.2,0,.3,1)'});
      leave.onfinish=()=>{if(!demoCard.isConnected)return;demoIndex=(demoIndex+1)%DEMO_NOTES.length;const p=proposalMap.get(DEMO_NOTES[demoIndex].id);demoCard.querySelector('.note-stamp')?.remove();
        demoCard.querySelector('.topic').innerHTML=`${icon(themeIcons[p.area],17)} ${AREAS[p.area]}`;demoCard.querySelector('.preview-proposal').textContent=p.texto;demoCard.querySelector('.proposal-context').textContent=p.contexto;
        demoCard.animate([{transform:'translate(9px,7px) rotate(1.8deg)',backgroundColor:'#f1f3ea'},{transform:'rotate(-.6deg)',backgroundColor:'#fffef9'}],{duration:480,easing:'cubic-bezier(.16,1,.3,1)'});};};
    const loop=setInterval(step,4600);const prevDemo=landingCleanup;landingCleanup=()=>{clearInterval(loop);seen.disconnect();prevDemo?.();};}
  const video=document.querySelector('#explainer-video');if(!video)return;
  const button=document.querySelector('[data-action="video-toggle"]');let visible=false,manualPause=false,manualPlay=false;
  const update=()=>{button.setAttribute('aria-label',video.paused?'Reproduzir vídeo explicativo':'Pausar vídeo explicativo');button.innerHTML=icon(video.paused?'play':'pause',20);button.classList.toggle('is-paused',video.paused);};
  const sync=()=>{if(visible&&!document.hidden&&!manualPause&&(!reduced.matches||manualPlay))video.play().catch(update);else video.pause();};
  const observer=new IntersectionObserver(entries=>{visible=entries[0].intersectionRatio>=.45;sync();},{threshold:[0,.45]});observer.observe(video);
  const toggle=()=>{if(video.paused){manualPause=false;manualPlay=true;video.play().catch(update);}else{manualPause=true;video.pause();}};
  button.addEventListener('click',toggle);video.addEventListener('play',update);video.addEventListener('pause',update);
  const preference=()=>{manualPlay=false;sync();};reduced.addEventListener('change',preference);document.addEventListener('visibilitychange',sync);
  const earlierCleanup=landingCleanup;landingCleanup=()=>{earlierCleanup?.();observer.disconnect();reduced.removeEventListener('change',preference);document.removeEventListener('visibilitychange',sync);};update();
}
// The answer is stamped on top of the note, in the colour of its button.
function noteStamp(card,value){
  let s=card.querySelector('.note-stamp');
  if(!s||s.dataset.answer!==value){s?.remove();s=document.createElement('span');s.className=`note-stamp note-stamp-${value}`;s.dataset.answer=value;s.setAttribute('aria-hidden','true');s.textContent=ANSWERS[value].label+(value==='important'?' ×2':'');card.append(s);}
  return s;
}
// Phone: size the proposal so text and context fill about 80% of the note, between 22px and 46px.
let fitObserver=null;
function fitProposal(){
  const copy=document.querySelector('#proposal-card .proposal-copy');if(!copy)return;
  const h2=copy.querySelector('h2'),context=copy.querySelector('.proposal-context');
  if(!matchMedia('(max-width: 650px)').matches){h2.style.fontSize='';return;}
  const room=copy.clientHeight*.8,gap=parseFloat(getComputedStyle(context).marginTop)||0;let lo=22,hi=46;
  for(let i=0;i<8;i++){const mid=(lo+hi)/2;h2.style.fontSize=mid+'px';if(h2.offsetHeight+gap+context.offsetHeight<=room)lo=mid;else hi=mid;}
  h2.style.fontSize=Math.floor(lo)+'px';
}
function bindFit(){fitObserver?.disconnect();const copy=document.querySelector('#proposal-card .proposal-copy');if(!copy)return;fitProposal();document.fonts?.ready.then(fitProposal);fitObserver=new ResizeObserver(()=>fitProposal());fitObserver.observe(copy);}
// Touch: the note follows the finger sideways; past 80px it is answered, otherwise it settles back on the pad.
function bindSwipe(){
  const card=document.querySelector('#proposal-card');let touch=null,dragging=false;
  // Past 40px the matching button lights up and its stamp fades in on the note, fully visible at 80px.
  const lean=(side,dx=0)=>{document.querySelectorAll('[data-answer="agree"],[data-answer="disagree"]').forEach(b=>b.classList.toggle('is-leaning',b.dataset.answer===side));
    if(!side){card.querySelector('.note-stamp')?.remove();return;}
    const s=noteStamp(card,side);s.classList.add('is-preview');s.style.opacity=Math.min(1,(Math.abs(dx)-40)/40);};
  const settle=()=>{card.classList.remove('is-dragging');lean(null);card.style.transition='transform .28s cubic-bezier(.16,1,.3,1)';card.style.transform='';setTimeout(()=>{card.style.transition='';},300);};
  card.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'||busy)return;touch={x:e.clientX,y:e.clientY,id:e.pointerId};dragging=false;});
  card.addEventListener('pointermove',e=>{if(!touch||e.pointerId!==touch.id)return;const dx=e.clientX-touch.x,dy=e.clientY-touch.y;
    if(!dragging){if(Math.abs(dx)<10||Math.abs(dx)<Math.abs(dy)*1.3)return;dragging=true;card.setPointerCapture?.(e.pointerId);card.classList.add('is-dragging');}
    card.style.transform=`translateX(${dx}px) rotate(${dx/22}deg)`;lean(dx>40?'agree':dx<-40?'disagree':null,dx);});
  card.addEventListener('pointerup',e=>{if(!touch)return;const dx=e.clientX-touch.x;touch=null;if(dragging&&Math.abs(dx)>80){card.classList.remove('is-dragging');answer(dx>0?'agree':'disagree');}else if(dragging)settle();dragging=false;});
  card.addEventListener('pointercancel',()=>{touch=null;if(dragging)settle();dragging=false;});
}
async function share(){const r=result();const text=r.status==='winner'?`No voteAI, tive ${r.percentages[r.winner]}% de afinidade com ${CANDIDATES[r.winner].name}. Primeiro as ideias. Depois os nomes.`:r.status==='tie'?'Minhas respostas empataram no voteAI. Primeiro as ideias. Depois os nomes.':'Conheça propostas às cegas no voteAI. Primeiro as ideias. Depois os nomes.';const url=location.href.split('#')[0];try{if(navigator.share){await navigator.share({title:'Minha afinidade no voteAI',text,url});return;}if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(`${text}\n${url}`);toast('Resumo e link copiados. Suas respostas individuais não são compartilhadas.');return;}}catch(e){if(e.name==='AbortError')return;}const fallback=document.querySelector('#share-fallback');fallback.hidden=false;fallback.innerHTML=`<label>Copie seu resumo<textarea readonly>${esc(text+'\n'+url)}</textarea></label>`;fallback.querySelector('textarea').select();}
app.addEventListener('click',e=>{
  const btn=e.target.closest('button');if(!btn)return;
  if(btn.dataset.answer){if(btn.dataset.demo){start(DEMO_NOTES[demoIndex].id);}answer(btn.dataset.answer);return;}
  const action=btn.dataset.action;
  if(action==='start')start();
  if(action==='resume')resume();
  if(action==='home')navigate('home');
  if(action==='back'&&!busy&&session.index>0){session.index--;session.revealed=false;persist();noteEntry='return';render({focus:true,scroll:false});}
  if(action==='reveal')reveal();
  if(action==='skip-animation')finishReveal();
  if(action==='sound'){sound=!sound;confirmationSound.setEnabled(sound);if(sound)confirmationSound.unlock();btn.setAttribute('aria-pressed',sound);btn.setAttribute('aria-label',`Som ${sound?'ativado':'desativado'}`);btn.innerHTML=view==='quiz'?icon(sound?'volume':'mute',15):`${icon(sound?'volume':'mute',17)} Som ${sound?'ativado':'desativado'}`;}
  if(action==='key'){toast('Aqui, você vota em ideias. A urna compara as respostas automaticamente.');}
  if(action==='repeat-sound'){sound=true;confirmationSound.setEnabled(true);confirmationSound.unlock();playConfirmation();}
  if(action==='blank')toast('O voteAI compara ideias. Para registrar um voto em branco, use a urna oficial no dia da eleição.');
  if(action==='correct'){if(view==='urn'&&!busy){session.index=24;session.revealed=false;persist();navigate('quiz');}else if(view==='result'){review=true;render({scroll:false});document.querySelector('#review-section').scrollIntoView({behavior:'smooth'});}}
  if(action==='review'){review=true;render({scroll:false});const section=document.querySelector('#review-section');section.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});section.setAttribute('tabindex','-1');section.focus({preventScroll:true});}
  if(action==='share')share();
  if(action==='clear'){try{storage?.removeItem(SESSION_KEY);}catch{}session=null;toast('Respostas apagadas deste aparelho.');}
});
app.addEventListener('input',e=>{if(e.target.id==='source-search'){search=e.target.value;filterSources();}});
app.addEventListener('change',e=>{if(e.target.id==='source-filter'){filter=e.target.value;filterSources();}});
document.addEventListener('keydown',e=>{if(view!=='quiz'||e.altKey||e.metaKey||e.ctrlKey||e.target.matches('input,select,textarea')||e.target.closest('.proposal-copy'))return;const value={ArrowLeft:'disagree',ArrowRight:'agree',ArrowUp:'important',ArrowDown:'skip'}[e.key];if(value){e.preventDefault();answer(value);}});
function route(){const hash=location.hash;clearSim();busy=false;if(hash==='#fontes')view='sources';else if(hash==='#teste'&&session&&session.index<25)view='quiz';else if(['#urna','#resultado'].includes(hash)&&session?.index===25)view=session.revealed?'result':'urn';else view='home';render({focus:false});if(view==='home'&&hash.length>1&&hash!=='#inicio')document.getElementById(hash.slice(1))?.scrollIntoView({behavior:'smooth'});}
window.addEventListener('hashchange',route);route();
